Great choices! Let's start with the auth middleware:

```typescript
import jwt from 'jsonwebtoken';
import { Request, Response, NextFunction } from 'express';

interface JwtPayload {
  userId: string;
}

export const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET!) as JwtPayload;
    req.userId = decoded.userId;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};
```

Make sure to add `JWT_SECRET` to your `.env` file.

Here's a complete login route:

```typescript
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

app.post('/api/auth/login', async (req, res) => {
  const { email, password } = req.body;

  // Find user
  const user = await User.findOne({ email });
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Verify password
  const isValid = await bcrypt.compare(password, user.passwordHash);
  if (!isValid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Generate token
  const token = jwt.sign(
    { userId: user.id },
    process.env.JWT_SECRET!,
    { expiresIn: '7d' }
  );

  res.json({ token, user: { id: user.id, email: user.email } });
});
```

Note: Never reveal whether the email or password was wrong - always use a generic "Invalid credentials" message for security.

For token refresh, you have two common approaches:

**Option 1: Refresh Token (Recommended)**
- Issue a short-lived access token (15 min) and long-lived refresh token (7 days)
- Store refresh token in httpOnly cookie
- Create a `/refresh` endpoint

**Option 2: Sliding Expiration**
- Check token expiry on each request
- Issue new token if close to expiring

Here's a simple refresh implementation:

```typescript
app.post('/api/auth/refresh', (req, res) => {
  const refreshToken = req.cookies.refreshToken;

  try {
    const decoded = jwt.verify(refreshToken, process.env.REFRESH_SECRET!);
    const newAccessToken = jwt.sign(
      { userId: decoded.userId },
      process.env.JWT_SECRET!,
      { expiresIn: '15m' }
    );
    res.json({ token: newAccessToken });
  } catch {
    res.status(401).json({ error: 'Invalid refresh token' });
  }
});
```
